command:example.dev:code:
PS C:\> $getParams @{
..      LDAPFilter = "(objectClass=site)"
..      SearchBase = 'CN=Configuration,DC=Fabrikam,DC=Com'
..      Properties = "canonicalName"
..  }
PS C:\> Get-OpenADObject @getParams | Select-Object Name, canonicalName

PS C:\> $newParams = @{
    Name = "192.168.1.0/26"
    Type = "subnet"
    Description = "192.168.1.0/255.255.255.192"
    OtherAttributes = @{
        location = "Building A"
        siteObject = "CN=HQ,CN=Sites,CN=Configuration,DC=FABRIKAM,DC=COM"
    }
    Path = "CN=Subnets,CN=Sites,CN=Configuration,DC=FABRIKAM,DC=COM"
}
PS C:\> New-OpenADObject @newParams

PS C:\> $newParams = @{
    Name = "UserContact"
    Type = "contact"
    OtherAttributes = @{
        'msDS-SourceObjectDN' = 'CN=FabrikamContacts,DC=domain,DC=test'
    }
}
PS C:\> New-OpenADObject @newParams

PS C:\> $newParams = @{
    Name = 'MyGroup'
    Type = 'group'
    Path = 'CN=Users,DC=domain,DC=test'
    OtherAttributes = @{
        sAMAccountName = 'MyGroup'
    }
}
PS C:\> New-OpenADObject @newParams

PS C:\> $addProps = @{
    'msDS-AllowedToDelegateTo' = 'CN=FileServer,OU=Servers,DC=domain,DC=test'
    networkAddress = '192.168.1.1', '192.168.1.2'
}
PS C:\> Get-OpenADUser user | Set-OpenADObject -Add $addProps

PS C:\> $replaceProps = @{
    servicePrincipalName = 'HOST/host1', 'HOST/host1.domain.com'
}
PS C:\> Get-OpenADComputer COMPUTER | Set-OpenADObject -Replace $replaceProps

PS C:\> $user = Get-OpenADUser user -Property userAccountControl
PS C:\> $newUAC = $user.UserAccountControl -bor [PSOpenAD.UserAccountControl]::DontExpirePassword
PS C:\> $user | Set-OpenADObject -Replace @{ userAccountControl = $newUAC }
